// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  DownloadIcon,
  FileJsonIcon,
  FileSpreadsheetIcon,
  FileTextIcon,
  GaugeIcon,
  GlobeIcon,
  RadarIcon,
  SlidersHorizontalIcon,
  TimerIcon,
  Trash2Icon,
  UploadIcon,
  WifiIcon,
  WifiLowIcon,
} from 'lucide-react'
import type { ReactNode } from 'react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import {
  BACK,
  CAPTIONS,
  CHART,
  CSV,
  CSV_FILE,
  DATE,
  DROP,
  END,
  EXPORTS,
  INTERVAL_S,
  IP,
  LATENCY_COLOR,
  LINE,
  LIVE_LABEL,
  LOG,
  PING_HOST,
  START,
  STATUS_COLOR,
  TODAY_BEFORE,
  X_DROP,
  X_START,
  availabilityColor,
  formatAvailability,
  formatClockDuration,
  formatLatency,
  formatTime,
  stateAt,
  xAt,
} from './script'

const SPEED = 5

const build: Build = ({ tl, q, qa, step, final, move, click, wait, cursorOut }) => {
  const el = {
    forText: q('live-for'),
    latency: q('live-lat'),
    clip: q('clip'),
    shade: q('shade'),
    count: q('sum-count'),
    avg: q('sum-avg'),
    min: q('sum-min'),
    max: q('sum-max'),
    avail: q('avail'),
    bar: q('avail-bar'),
    disc: q('disc'),
    down: q('down'),
  }
  const render = (t: number) => {
    const state = stateAt(t)
    el.forText.textContent = `for ${formatClockDuration(state.forMs)}`
    el.latency.textContent = formatLatency(state.latency)
    el.clip.setAttribute('width', xAt(t).toFixed(1))
    el.shade.setAttribute('width', Math.max(0, xAt(Math.min(t, BACK)) - X_DROP).toFixed(1))
    el.count.textContent = String(state.count)
    el.avg.textContent = formatLatency(state.summary.avg)
    el.min.textContent = formatLatency(state.summary.min)
    el.max.textContent = formatLatency(state.summary.max)
    el.avail.textContent = formatAvailability(state.today.availability)
    el.avail.style.color = availabilityColor(state.today.availability)
    el.bar.style.backgroundColor = availabilityColor(state.today.availability)
    el.bar.style.transform = `scaleX(${state.today.availability ?? 0})`
    el.disc.textContent = String(state.today.disconnects)
    el.down.textContent = formatClockDuration(state.today.downtimeMs)
  }
  const advance = (from: number, to: number, speed = SPEED) => {
    const proxy = { t: from }
    tl.to(proxy, {
      t: to,
      duration: (to - from) / 1000 / speed,
      ease: 'none',
      immediateRender: false,
      onUpdate: () => render(proxy.t),
    })
  }
  const status = (key: 'online' | 'lan') => {
    const color = STATUS_COLOR[key]
    tl.set(q('live-label'), { text: LIVE_LABEL[key] })
    tl.to([q('live-label'), q('tile')], { color, duration: 0.25 }, '<')
    tl.to(q('live-dot'), { backgroundColor: color, duration: 0.25 }, '<')
    tl.to(
      q('tile'),
      { borderColor: `${color}55`, backgroundColor: `${color}1f`, duration: 0.25 },
      '<',
    )
    tl.to(
      q('glow'),
      {
        background: `radial-gradient(120% 90% at 0% 0%, ${color}2e, transparent 62%)`,
        duration: 0.4,
      },
      '<',
    )
    tl.to(q('icon-online'), { opacity: key === 'online' ? 1 : 0, duration: 0.2 }, '<')
    tl.to(q('icon-lan'), { opacity: key === 'lan' ? 1 : 0, duration: 0.2 }, '<')
    tl.fromTo(
      q('live-dot-ring'),
      { scale: 1, opacity: 0.7 },
      { scale: 2.6, opacity: 0, duration: 0.7, immediateRender: false },
      '<',
    )
  }

  step(0)
  move('chart', { at: 0.2, ax: 0.7 })
  advance(START, DROP - INTERVAL_S * 1000)
  move('live-lat', { at: '<0.6' })
  advance(DROP - INTERVAL_S * 1000, DROP)

  step(1, '+=0.1')
  status('lan')
  move('live-label', { at: '<', ax: 0.3 })
  advance(DROP, BACK, 9)
  status('online')
  move('today', { at: '<', ax: 0.5 })
  tl.fromTo(
    q('disc'),
    { scale: 1.5, color: STATUS_COLOR.lan },
    { scale: 1, color: '#e4e4e7', duration: 0.5, immediateRender: false },
    '<',
  )
  advance(BACK, END)
  wait(0.4)

  step(2, '+=0.1')
  move('tab-1')
  click('tab-1')
  tl.to(
    qa('tab'),
    { backgroundColor: 'rgba(255,255,255,0)', color: 'var(--demo-muted)', duration: 0.15 },
    '<',
  )
  tl.to(
    q('tab-1'),
    { backgroundColor: 'var(--demo-tint-10)', color: 'var(--demo-ink)', duration: 0.15 },
    '<',
  )
  tl.to(q('view-rt'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('view-log'), { opacity: 1, duration: 0.2 }, '<0.1')
  tl.fromTo(
    qa('log-row'),
    { opacity: 0, x: 6 },
    { opacity: 1, x: 0, duration: 0.25, stagger: 0.07, immediateRender: false },
    '<',
  )
  move('export')
  click('export')
  tl.fromTo(
    q('menu'),
    { opacity: 0, y: -4 },
    { opacity: 1, y: 0, duration: 0.15, immediateRender: false },
    '<',
  )
  move('menu-0')
  tl.to(q('menu-0'), { backgroundColor: 'var(--demo-tint-8)', duration: 0.1 })
  click('menu-0')
  tl.to(q('menu'), { opacity: 0, duration: 0.12 }, '<')
  tl.fromTo(
    q('toast'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.35, ease: 'power3.out', immediateRender: false },
    '<0.1',
  )
  cursorOut('+=0.4')
  final('+=0.1')
  wait(2.4)

  const reset = () => render(START)
  tl.call(reset, [], 0)
  tl.set([q('view-log'), q('menu'), q('toast'), q('icon-lan')], { opacity: 0 }, 0)
  tl.set([q('view-rt'), q('icon-online'), ...qa('log-row')], { opacity: 1 }, 0)
  tl.set(q('menu-0'), { backgroundColor: 'rgba(255,255,255,0)' }, 0)
  tl.set(qa('tab'), { backgroundColor: 'rgba(255,255,255,0)', color: 'var(--demo-muted)' }, 0)
  tl.set(q('tab-0'), { backgroundColor: 'var(--demo-tint-10)', color: 'var(--demo-ink)' }, 0)
  tl.set(q('live-label'), { text: LIVE_LABEL.online, color: STATUS_COLOR.online }, 0)
  tl.set(
    q('tile'),
    {
      color: STATUS_COLOR.online,
      borderColor: `${STATUS_COLOR.online}55`,
      backgroundColor: `${STATUS_COLOR.online}1f`,
    },
    0,
  )
  tl.set(q('live-dot'), { backgroundColor: STATUS_COLOR.online }, 0)
  tl.set(
    q('glow'),
    { background: `radial-gradient(120% 90% at 0% 0%, ${STATUS_COLOR.online}2e, transparent 62%)` },
    0,
  )
  reset()
}

function Fact({ icon, label, children }: { icon: ReactNode; label: string; children: ReactNode }) {
  return (
    <span className="min-w-0 rounded-md border border-line bg-canvas/60 px-1.5 py-1">
      <span className="flex items-center gap-1 text-[7px] text-muted">
        {icon}
        {label}
      </span>
      <span className="mt-0.5 block truncate font-mono text-[8.5px] font-medium text-ink">
        {children}
      </span>
    </span>
  )
}

